/* Read-only argument-map results and single-expert chat. All content is a fixture. */
const directChatTimers=new Map();
function renderExperts(){
  const list=experts.filter(e=>(e.role+' '+e.domain).toLowerCase().includes(state.expertQuery.toLowerCase())&&(state.expertDomain==='all'||e.domain===state.expertDomain));
  return heading('EXPERT WORKSPACE','Chuyên môn bắt đầu từ đây.','Khám phá hồ sơ hoặc trao đổi trực tiếp với một chuyên gia AI.',btn(ico('plus')+' Tạo expert','new-expert','primary'))+`<div class="library-toolbar"><div class="search-box">${ico('search')}<input id="expert-search" data-field="expertQuery" value="${esc(state.expertQuery)}" placeholder="Tìm theo chuyên môn hoặc lĩnh vực…" aria-label="Tìm expert"></div><select style="max-width:200px" data-action-change="domain" aria-label="Lĩnh vực"><option value="all">Tất cả lĩnh vực</option>${[...new Set(experts.map(e=>e.domain))].map(d=>`<option ${d===state.expertDomain?'selected':''}>${esc(d)}</option>`).join('')}</select><span class="small muted">${list.length} expert</span></div><div class="grid3">${list.map(e=>`<article class="card expert-card"><button class="expert-card-profile" data-action="expert-profile" data-id="${e.id}" aria-label="Xem hồ sơ ${esc(e.role)}"><div class="between">${avatar(e)}${badge(e.domain,e.color==='purple'?'purple':'')}</div><h3>${esc(e.role)}</h3><p>${esc(e.approach)}</p></button><div class="row wrap">${e.skills.map(s=>badge(s)).join('')}</div><div class="expert-footer expert-chat-footer"><button class="text-button" data-action="expert-profile" data-id="${e.id}">Xem hồ sơ</button>${btn(ico('chat')+' Trao đổi riêng','direct-chat','small subtle',`data-id="${e.id}" data-from="experts"`)}</div></article>`).join('')||'<div class="empty">Không có expert phù hợp.</div>'}</div>`;
}
function argumentItems(run=state.run){
  return run.results.flatMap(result=>{
    const base={id:result.stepId,stepId:result.stepId,title:result.title,text:result.summary,kind:'finding',experts:result.experts.map(e=>e.id),evidence:result.evidence,rating:result.rating};
    const dissenters=result.experts.filter(e=>e.final&&result.rating&&e.final!==result.rating);
    return [base,...(dissenters.length?[{id:result.stepId+'-dissent',stepId:result.stepId,title:'Quan điểm khác · '+result.title,text:result.dissent,kind:'dissent',experts:dissenters.map(e=>e.id),evidence:result.evidence,rating:dissenters[0].final}]:[])];
  });
}
function currentArgument(){const items=argumentItems();return items.find(a=>a.id===state.argumentId)||items[0]||null;}
function argumentOpinionCount(run,id){return run.results.reduce((n,r)=>n+r.experts.filter(e=>!id||e.id===id).length,0);}
function renderDiscussionDashboard(){
  const run=state.run;if(!run)return '<div class="empty">Chưa có kết quả.</div>';
  const items=argumentItems(run),selected=currentArgument(),dissent=items.filter(a=>a.kind==='dissent').length;
  return `<header class="discussion-header"><div><div class="eyebrow">DISCUSSION RESULTS · SAMPLE</div><h1>${esc(run.plan.title)}</h1><div class="row discussion-meta">${ico('expert')} ${run.plan.experts.length} experts <span>·</span> ${run.results.length} / ${run.plan.steps.length} tasks <span>·</span> ${elapsedLabel(run.durationMs||0)} ${badge(run.status==='completed'?'Đã hoàn tất':'Thoát sớm',run.status==='completed'?'green':'amber')}</div></div><div class="row discussion-actions">${btn(ico('plan')+' Xem báo cáo','dashboard-mode','small','data-view="report"')}${btn(ico('download')+' Xuất','export','small')}${btn(ico('link')+' Chia sẻ','share','small')}</div></header><div class="discussion-board"><aside class="case-participants"><div class="between"><h3>Participants</h3><span class="muted small">${run.plan.experts.length}</span></div><button class="participant-all ${!state.feedExpert?'active':''}" data-action="filter-participant" data-id="">Tất cả chuyên gia</button>${run.plan.experts.map(e=>{const different=run.results.some(r=>r.experts.some(v=>v.id===e.id&&v.final&&r.rating&&v.final!==r.rating)||(r.disagreements||[]).some(d=>d.expertViews.some(v=>v.expert===e.id)));return `<button class="participant-item ${state.feedExpert===e.id?'active':''}" data-action="filter-participant" data-id="${e.id}">${avatar(e)}<span><strong>${esc(e.role)}</strong><small>${different?'Còn ý kiến khác':'Đã đóng góp'} · ${argumentOpinionCount(run,e.id)}</small></span></button>`;}).join('')}<div class="case-insights"><h3>Discussion insights</h3><div><span>Luận điểm</span><strong>${items.length}</strong></div><div><span>Quan điểm expert</span><strong>${argumentOpinionCount(run)}</strong></div><div><span>Điểm chưa thống nhất</span><strong>${dissent}</strong></div><div><span>Nguồn được dẫn</span><strong>${new Set(run.results.flatMap(r=>r.evidence.map(e=>e.doc))).size}</strong></div><p>Kết quả AI mẫu. Bất đồng được giữ nguyên; chưa được người thật phê duyệt.</p></div>${backButton('cases','Quay lại Cases')}</aside><div class="discussion-center"><section class="argument-panel"><div class="argument-toolbar"><h3 class="row">${ico('graph')} Argument map</h3><span class="argument-view-label">Kết luận & bất đồng</span><div class="graph-controls">${btn('−','argument-out','small icon-btn','aria-label="Thu nhỏ argument map"')}<span id="argument-zoom">100%</span>${btn('+','argument-in','small icon-btn','aria-label="Phóng to argument map"')}${btn('Fit','argument-fit','small')}</div></div>${renderArgumentMap(items,selected)}<footer class="argument-legend"><span><i class="finding-dot"></i> Kết luận theo cấu phần</span><span><i class="dissent-dot"></i> Quan điểm khác</span><span>Chọn một luận điểm để truy nguồn</span></footer></section><section class="discussion-feed"><div class="feed-heading"><h3>Ý kiến chuyên gia</h3><div class="feed-filters">${[['all','Tất cả'],['selected','Luận điểm đang chọn'],['dissent','Bất đồng']].map(([key,label])=>`<button class="${state.feedFilter===key?'active':''}" data-action="feed-filter" data-filter="${key}">${label}</button>`).join('')}</div></div><div class="feed-cards" data-scroll="discussion-feed">${renderOpinionFeed(run,selected)}</div></section></div><aside class="argument-inspector" aria-label="Chi tiết luận điểm" data-scroll="argument-detail">${renderArgumentDetail(selected,run)}</aside></div>`;
}
function renderArgumentMap(items,selected){
  const rows=Math.max(1,Math.ceil(items.length/2)),width=900,height=Math.max(260,rows*116+24);
  const root={x:348,y:height/2-48,w:204,h:96};
  const positions={};items.forEach((a,i)=>{const side=i%2,row=Math.floor(i/2),count=Math.ceil((items.length-side)/2);positions[a.id]={x:side?634:14,y:(height-count*116)/2+row*116+10};});
  const edges=items.map(a=>{const p=positions[a.id],left=p.x<root.x,start=left?{x:p.x+252,y:p.y+52}:{x:root.x+root.w,y:root.y+48},end=left?{x:root.x,y:root.y+48}:{x:p.x,y:p.y+52};return `<path d="M${start.x} ${start.y} C${start.x+28} ${start.y},${end.x-28} ${end.y},${end.x} ${end.y}" class="argument-edge ${a.kind}"/>`;}).join('');
  return `<div id="argument-viewport" class="argument-viewport" aria-label="Sơ đồ luận điểm: chọn card để xem chi tiết; kéo nền hoặc zoom"><div id="argument-scene" class="argument-scene" data-width="${width}" data-height="${height}" style="width:${width}px;height:${height}px"><svg class="argument-edges" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" aria-hidden="true">${edges}</svg><div class="argument-topic" style="left:${root.x}px;top:${root.y}px"><span>${ico('expert')} ${state.run.plan.experts.length} experts</span><h3>${esc(state.run.plan.title)}</h3><small>${items.length} luận điểm · ${state.run.results.length} tasks</small></div>${items.map(a=>`<button class="argument-card ${a.kind} ${a.id===selected?.id?'selected':''} ${state.feedExpert&&!a.experts.includes(state.feedExpert)?'dimmed':''}" style="left:${positions[a.id].x}px;top:${positions[a.id].y}px" data-action="select-argument" data-id="${a.id}" aria-pressed="${a.id===selected?.id}"><div class="argument-card-heading"><span class="argument-kind-icon">${a.kind==='dissent'?'!':'✓'}</span><h3>${esc(a.title)}</h3><span>${a.rating?esc(a.rating):'Mẫu'}</span></div><p>${esc(a.text)}</p><div class="argument-card-footer"><span>${a.experts.length} expert</span><span>${a.evidence.length} dẫn nguồn</span></div></button>`).join('')}${!items.length?'<div class="argument-empty">Chưa có task hoàn tất. Không có luận điểm để tổng hợp.</div>':''}</div></div>`;
}
function renderOpinionFeed(run,selected){
  const opinions=run.results.flatMap(r=>r.experts.map(e=>({result:r,expert:e})));
  const list=opinions.filter(({result:r,expert:e})=>(!state.feedExpert||state.feedExpert===e.id)&&(state.feedFilter!=='selected'||r.stepId===selected?.stepId)&&(state.feedFilter!=='dissent'||e.final&&r.rating&&e.final!==r.rating));
  return list.map(({result:r,expert:e})=>`<button class="opinion-card" data-action="select-argument" data-id="${e.final&&r.rating&&e.final!==r.rating?r.stepId+'-dissent':r.stepId}"><div class="row">${avatar(run.plan.experts.find(x=>x.id===e.id))}<strong>${esc(e.role)}</strong></div><div class="row opinion-meta">${badge(r.stepId)}${badge(e.final||'Mẫu',e.final&&r.rating&&e.final!==r.rating?'amber':'green')}</div><p>${esc(e.view)}</p><span>${e.initial?`${esc(e.initial)} → ${esc(e.final)}`:'Nhận định mẫu'} · Xem trong argument map ↗</span></button>`).join('')||'<div class="empty">Không có ý kiến phù hợp bộ lọc.</div>';
}
function renderArgumentDetail(argument,run){
  if(!argument)return '<div class="empty">Chưa có luận điểm để xem.</div>';
  const result=run.results.find(r=>r.stepId===argument.stepId);
  return `<div class="argument-detail-heading"><span>Selected argument</span>${badge(argument.kind==='dissent'?'Bất đồng':'Kết luận',argument.kind==='dissent'?'amber':'green')}</div><h2>${esc(argument.title)}</h2><p class="argument-detail-summary">${esc(argument.text)}</p><div class="argument-detail-section"><h3>Quan điểm chuyên gia</h3>${result.experts.map(e=>`<article class="expert-view"><div class="row">${avatar(run.plan.experts.find(x=>x.id===e.id))}<div><strong>${esc(e.role)}</strong><span>${e.final?esc(e.final):'Đầu ra mẫu'}</span></div></div><p>${esc(e.view)}</p><small>${e.initial?`Đánh giá đầu: ${esc(e.initial)} · Sau phản biện: ${esc(e.final)}`:'Chưa có rating chuẩn hóa.'}</small></article>`).join('')}</div><div class="argument-detail-section"><h3>Bất đồng & giới hạn</h3><p>${esc(result.dissent)}</p></div><div class="argument-detail-section"><h3>Nguồn tham khảo</h3>${argument.evidence.map(e=>`<button class="argument-source" data-action="document" data-id="${e.doc}">${ico('file')}<span>${esc(currentDocument(e.doc)?.name||e.doc)}<small>${esc(e.ref)} · “${esc(e.quote)}”</small></span>${ico('arrow')}</button>`).join('')||'<p>Chưa có dẫn nguồn thực tế cho cấu hình này.</p>'}</div>${btn('Chi tiết task '+ico('arrow'),'result-detail','small','data-id="'+result.stepId+'"')}`;
}
function syncArgumentMap(){
  const viewport=$('#argument-viewport'),scene=$('#argument-scene');if(!viewport||!scene)return;
  const view=state.argumentView;
  if(view.auto){const w=Number(scene.dataset.width),h=Number(scene.dataset.height);view.zoom=Math.max(view.fitAll ? .2 : .85,Math.min(1.12,(viewport.clientWidth-16)/w,(viewport.clientHeight-16)/h));view.x=(viewport.clientWidth-w*view.zoom)/2;view.y=(viewport.clientHeight-h*view.zoom)/2;}
  scene.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.zoom})`;
  const zoom=$('#argument-zoom');if(zoom)zoom.textContent=Math.round(view.zoom*100)+'%';
}
function zoomArguments(factor){const viewport=$('#argument-viewport');if(!viewport)return;const v=state.argumentView,old=v.zoom,next=Math.max(.2,Math.min(2,old*factor));v.x=viewport.clientWidth/2-(viewport.clientWidth/2-v.x)*next/old;v.y=viewport.clientHeight/2-(viewport.clientHeight/2-v.y)*next/old;v.zoom=next;v.auto=false;syncArgumentMap();}
function renderDirectPicker(){
  const list=experts.filter(e=>(e.role+' '+e.domain).toLowerCase().includes(state.directExpertQuery.toLowerCase()));
  return `${backButton(state.chatReturn||'templates',state.chatReturn==='experts'?'Quay lại danh sách expert':'Quay lại tạo case')}${heading('DIRECT EXCHANGE','Bạn muốn trao đổi với chuyên gia nào?','Chọn đúng một expert. Cuộc trao đổi này không cần template hoặc plan.')}<div class="direct-picker-layout"><section><div class="search-box section-title">${ico('search')}<input id="direct-expert-search" data-field="directExpertQuery" value="${esc(state.directExpertQuery)}" placeholder="Tìm chuyên gia…" aria-label="Tìm chuyên gia để trao đổi"></div><div class="direct-expert-list">${list.map(e=>`<label class="direct-expert-option ${state.directExpertId===e.id?'selected':''}"><input type="radio" name="direct-expert" data-direct-expert value="${e.id}" ${state.directExpertId===e.id?'checked':''}>${avatar(e)}<span><strong>${esc(e.role)}</strong><small>${esc(e.domain)} · ${esc(e.approach)}</small></span></label>`).join('')||'<div class="empty">Không tìm thấy expert.</div>'}</div></section><aside class="card direct-picker-summary">${state.directExpertId?(()=>{const e=expertById(state.directExpertId);return `<div class="eyebrow">EXPERT ĐÃ CHỌN</div>${avatar(e)}<h2>${esc(e.role)}</h2><p>${esc(e.approach)}</p><div class="row wrap">${e.skills.map(s=>badge(s)).join('')}</div>`;})():`<span class="avatar">${ico('chat')}</span><h2>Một cuộc trao đổi, một chuyên gia.</h2><p>Chọn expert phù hợp với điều bạn muốn làm rõ.</p>`}<div class="notice">Đây là prototype frontend. Tin nhắn và câu trả lời mẫu chỉ được giữ trong phiên này.</div>${btn('Bắt đầu trao đổi '+ico('arrow'),'begin-direct-chat','primary',state.directExpertId?'':'disabled')}</aside></div>`;
}
function beginDirectChat(id,returnPage){
  const expert=expertById(id);if(!expert){toast('Chọn một expert trước.');return;}
  const chat={id:'chat-'+Date.now().toString(36)+'-'+state.chats.length,expert:clone(expert),title:'Trao đổi với '+expert.role,returnPage:returnPage||'templates',messages:[{role:'assistant',text:`Tôi sẽ trao đổi với bạn dưới góc nhìn ${expert.role}. Bạn muốn làm rõ vấn đề nào của AutoSupport?`,fixture:true}],pending:false};
  state.chats.push(chat);state.chatId=chat.id;state.chatDrafts[chat.id]='';go('chat');
}
function currentDirectChat(){return state.chats.find(c=>c.id===state.chatId);}
function renderDirectChat(){
  const chat=currentDirectChat();if(!chat)return '<div class="empty">Chưa chọn expert.</div>';
  const expert=chat.expert;
  return `<header class="direct-chat-header"><div class="row">${avatar(expert)}<div><div class="eyebrow">TRAO ĐỔI TRỰC TIẾP · 1 EXPERT</div><h1>${esc(expert.role)}</h1></div></div><div class="row">${backButton(chat.returnPage,chat.returnPage==='experts'?'Danh sách expert':'Tạo case')}${btn('Chọn expert khác','choose-direct-expert','small',`data-from="${chat.returnPage}"`)}</div></header><div class="direct-chat-layout"><section class="direct-conversation"><div class="chat-fixture-notice">Phản hồi mô phỏng · Không gọi model · Chỉ expert đã chọn tham gia</div><div class="chat-messages" id="chat-messages" data-scroll="chat-messages" role="log" aria-live="polite">${chat.messages.map(m=>`<article class="chat-message ${m.role}"><div class="chat-message-author">${m.role==='user'?'<span class="avatar user-avatar">TR</span>':avatar(expert)}<strong>${m.role==='user'?'Bạn':esc(expert.role)}</strong>${m.fixture?'<span>Phản hồi mẫu</span>':''}</div><div class="chat-message-text">${esc(m.text)}</div></article>`).join('')}${chat.pending?`<div class="chat-typing">${avatar(expert)}<span>Đang chuẩn bị phản hồi mẫu…</span><i></i><i></i><i></i></div>`:''}</div>${chat.messages.length===1?`<div class="chat-suggestions">${['Các rủi ro quan trọng của AutoSupport là gì?','Tôi nên chuẩn bị bằng chứng nào?','Gợi ý cách giảm thiểu rủi ro.'].map(q=>`<button data-action="chat-suggestion" data-text="${esc(q)}">${esc(q)}</button>`).join('')}</div>`:''}<form id="direct-chat-form" class="direct-composer"><label class="screen-reader" for="direct-message">Tin nhắn cho ${esc(expert.role)}</label><textarea id="direct-message" data-chat-draft placeholder="Đặt câu hỏi cho ${esc(expert.role)}…" maxlength="4000" required>${esc(state.chatDrafts[chat.id]||'')}</textarea><div class="between"><span>Chỉ ${esc(expert.role)} nhận tin nhắn này · Ctrl + Enter để gửi</span><button class="btn primary small" type="submit" ${chat.pending?'disabled':''}>Gửi ${ico('arrow')}</button></div></form></section><aside class="direct-chat-context"><div class="eyebrow">YOUR EXPERT</div><h2>${esc(expert.role)}</h2>${badge(expert.domain,'purple')}<h3>Cách đánh giá</h3><p>${esc(expert.approach)}</p><h3>Kỹ năng</h3><div class="stack" style="gap:8px">${expert.skills.map(s=>badge(s)).join('')}</div><details class="profile-skill"><summary>System instructions</summary><pre>${esc(expert.prompt||'Chưa có chỉ dẫn bổ sung.')}</pre></details><div class="notice gap">Không chạy hội đồng hoặc plan trong cuộc trao đổi riêng. Knowledge Base chưa triển khai.</div></aside></div>`;
}
function directFixtureReply(chat,text){
  const replies={safety:'Với góc nhìn an toàn AI, tôi sẽ bắt đầu từ ranh giới giữa chỉ dẫn đáng tin cậy và nội dung khách hàng. Hãy chuẩn bị các tình huống prompt injection, kết quả kiểm thử và bằng chứng về cách cô lập nội dung truy xuất. Khi chưa có các kiểm soát này, mức rủi ro chỉ là giả định cần kiểm chứng.',security:'Tôi sẽ rà soát quyền công cụ và các ranh giới tin cậy. Với AutoSupport, nên làm rõ service account được dùng như thế nào, quyền có gắn với người dùng cuối không, và kiểm soát nào chặn truy vấn vượt quyền. Hãy đưa ra một kịch bản tấn công cùng bằng chứng kiểm thử trước khi kết luận.',legal:'Từ góc nhìn dữ liệu và tuân thủ, tôi cần biết loại dữ liệu, mục đích sử dụng, quyền truy cập, thời gian lưu giữ và cơ chế xóa. Với AutoSupport, cần đặc biệt làm rõ việc che dữ liệu khi logging. Chưa có tài liệu đối chiếu thì chưa thể xác nhận tuân thủ.',operations:'Tôi ưu tiên khả năng vận hành: ai xử lý sự cố, log nào dùng để truy vết, và hệ thống trở về trạng thái an toàn bằng cách nào. Với AutoSupport, hãy kiểm tra quyền service account, khả năng giới hạn tác động và quy trình xử lý khi công cụ trả dữ liệu sai.',synthesizer:'Tôi sẽ tách các kết luận đã có bằng chứng khỏi giả định, ghi nhận quan điểm khác nhau và chỉ rõ điều kiện làm thay đổi quyết định. Bạn có thể bắt đầu bằng mục tiêu, các phương án và những điểm chưa thống nhất.'};
  return `Về câu hỏi “${text.slice(0,180)}${text.length>180?'…':''}”:\n\n${replies[chat.expert.id]||chat.expert.approach+' Trước tiên, hãy làm rõ mục tiêu, các giả định và bằng chứng hiện có. Tôi sẽ cấu trúc nhận định theo phạm vi chuyên môn đã được định nghĩa.'}\n\nBạn hiện đã có tài liệu hoặc kết quả kiểm thử nào để làm rõ điểm này?`;
}
function sendDirectMessage(){
  const chat=currentDirectChat(),text=(state.chatDrafts[chat?.id]||'').trim();if(!chat||chat.pending||!text)return;
  chat.messages.push({role:'user',text});if(!chat.namedCase&&chat.messages.filter(m=>m.role==='user').length===1)chat.title=text.slice(0,65);state.chatDrafts[chat.id]='';chat.pending=true;render();
  directChatTimers.set(chat.id,setTimeout(()=>{chat.messages.push({role:'assistant',text:directFixtureReply(chat,text),fixture:true});chat.pending=false;directChatTimers.delete(chat.id);if(state.page==='chat'&&state.chatId===chat.id)render();},1000));
}
function renderDirectChatCaseCards(){
  if(state.caseTab!=='mine')return '';
  return state.chats.filter(c=>(c.title+' '+c.expert.role).toLowerCase().includes(state.caseQuery.toLowerCase())).map(c=>`<article class="card stack"><div class="between">${badge('Trao đổi riêng','purple')}${avatar(c.expert)}</div><h3>${esc(c.title)}</h3><p class="small muted">${esc(c.expert.role)} · ${c.messages.filter(m=>m.role==='user').length} tin nhắn từ bạn</p>${btn('Tiếp tục trao đổi '+ico('arrow'),'resume-direct-chat','small',`data-id="${c.id}"`)}</article>`).join('');
}
function handleDiscussionAction(button){
  const action=button.dataset.action,id=button.dataset.id;
  if(action==='direct-chat'){state.chatReturn=button.dataset.from||'experts';beginDirectChat(id,state.chatReturn);return true;}
  if(action==='choose-direct-expert'){state.chatReturn=button.dataset.from||'templates';state.directExpertId=null;state.directExpertQuery='';go('direct-picker');return true;}
  if(action==='begin-direct-chat'){beginDirectChat(state.directExpertId,state.chatReturn);return true;}
  if(action==='resume-direct-chat'){state.chatId=id;go('chat');return true;}
  if(action==='chat-suggestion'){state.chatDrafts[state.chatId]=button.dataset.text;render();$('#direct-message')?.focus();return true;}
  if(action==='dashboard-mode'){state.dashboardView=button.dataset.view;state.argumentView.auto=true;render();return true;}
  if(action==='select-argument'){state.argumentId=id;render();return true;}
  if(action==='feed-filter'){state.feedFilter=button.dataset.filter;render();return true;}
  if(action==='filter-participant'){state.feedExpert=state.feedExpert===id?'':id;if(state.feedExpert){const first=argumentItems().find(a=>a.experts.includes(state.feedExpert));if(first)state.argumentId=first.id;}render();return true;}
  if(action==='argument-fit'){state.argumentView.fitAll=true;state.argumentView.auto=true;syncArgumentMap();return true;}
  if(action==='argument-in'){zoomArguments(1.2);return true;}
  if(action==='argument-out'){zoomArguments(1/1.2);return true;}
  return false;
}
let argumentDrag=null;
document.addEventListener('pointerdown',event=>{const viewport=event.target.closest('#argument-viewport');if(!viewport||event.target.closest('button')||event.button!==0)return;argumentDrag={pointer:event.pointerId,x:event.clientX,y:event.clientY,originX:state.argumentView.x,originY:state.argumentView.y};viewport.setPointerCapture(event.pointerId);viewport.classList.add('dragging');});
document.addEventListener('pointermove',event=>{if(!argumentDrag||event.pointerId!==argumentDrag.pointer)return;state.argumentView.auto=false;state.argumentView.x=argumentDrag.originX+event.clientX-argumentDrag.x;state.argumentView.y=argumentDrag.originY+event.clientY-argumentDrag.y;syncArgumentMap();});
function endArgumentDrag(){argumentDrag=null;$('#argument-viewport')?.classList.remove('dragging');}
document.addEventListener('pointerup',endArgumentDrag);
document.addEventListener('pointercancel',endArgumentDrag);
document.addEventListener('wheel',event=>{if(!event.target.closest('#argument-viewport'))return;event.preventDefault();zoomArguments(event.deltaY>0?1/1.08:1.08);},{passive:false});
